import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

export async function gate({ referenceDir, submissionDir }) {
  try {
    const answerPath = path.join(submissionDir, 'answer.mjs');
    if (!fs.existsSync(answerPath)) {
      return { accept: false, reason: 'answer.mjs not found in submission' };
    }
    const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');
    if (!fs.existsSync(pinnedPath)) {
      return { accept: false, reason: 'pinned-test-cases.txt missing from reference' };
    }
    const pinnedSource = fs.readFileSync(pinnedPath, 'utf8');
    const expectedCount = (pinnedSource.match(/\btest\s*\(/g) || []).length;
    if (expectedCount === 0) {
      return { accept: false, reason: 'could not parse any test cases from pinned file' };
    }

    const token = crypto.randomBytes(16).toString('hex');
    const finalFile = path.join(referenceDir, 'final-' + token + '.json');
    const progressFile = path.join(referenceDir, 'progress-' + token + '.json');
    try { fs.unlinkSync(finalFile); } catch (e) {}
    try { fs.unlinkSync(progressFile); } catch (e) {}

    const harnessSource = `
import fsMod from 'node:fs';
import pathMod from 'node:path';
import assertMod from 'node:assert/strict';
import { pathToFileURL } from 'node:url';

const referenceDir = process.argv[2];
const submissionDir = process.argv[3];
const token = process.argv[4];

const realWriteFileSync = fsMod.writeFileSync.bind(fsMod);
const finalPath = pathMod.join(referenceDir, 'final-' + token + '.json');
const progressPath = pathMod.join(referenceDir, 'progress-' + token + '.json');

const noop = function () {};
try { process.exit = noop; } catch (e) {}
try { process.abort = noop; } catch (e) {}
try { process.kill = noop; } catch (e) {}
const uncaughtLog = [];
const unhandledLog = [];
process.on('uncaughtException', function (err) {
  uncaughtLog.push(String(err && err.stack ? err.stack : err));
});
process.on('unhandledRejection', function (err) {
  unhandledLog.push(String(err && err.stack ? err.stack : err));
});

let dedupeSorted;
let importError = null;
try {
  const mod = await import(pathToFileURL(pathMod.join(submissionDir, 'answer.mjs')).href);
  dedupeSorted = mod.dedupeSorted;
} catch (e) {
  importError = String(e && e.stack ? e.stack : e);
}

const results = [];
let total = 0;

function test(name, fn) {
  total++;
  const idx = total;
  try {
    fn();
    results.push({ name: String(name), idx: idx, pass: true });
  } catch (e) {
    results.push({ name: String(name), idx: idx, pass: false, error: String(e && e.stack ? e.stack : e) });
  }
  try {
    realWriteFileSync(progressPath, JSON.stringify({ total: total, results: results }), 'utf8');
  } catch (e) {}
}

let evalError = null;
if (importError || typeof dedupeSorted !== 'function') {
  evalError = importError || 'dedupeSorted is not exported as a function';
} else {
  const pinnedSrc = fsMod.readFileSync(pathMod.join(referenceDir, 'pinned-test-cases.txt'), 'utf8');
  try {
    const runner = new Function('test', 'assert', 'dedupeSorted', pinnedSrc);
    runner(test, assertMod, dedupeSorted);
  } catch (e) {
    evalError = String(e && e.stack ? e.stack : e);
  }
}

try {
  realWriteFileSync(finalPath, JSON.stringify({
    completed: true,
    total: total,
    results: results,
    evalError: evalError,
    importError: importError,
    uncaught: uncaughtLog,
    unhandled: unhandledLog
  }), 'utf8');
} catch (e) {}
`;

    const harnessPath = path.join(referenceDir, 'harness-' + token + '.mjs');
    fs.writeFileSync(harnessPath, harnessSource, 'utf8');

    let spawnResult;
    try {
      spawnResult = spawnSync(process.execPath, [harnessPath, referenceDir, submissionDir, token], {
        timeout: 8000,
        encoding: 'utf8',
      });
    } catch (e) {
      return { accept: false, reason: 'failed to spawn test harness: ' + String(e && e.message ? e.message : e) };
    } finally {
      try { fs.unlinkSync(harnessPath); } catch (e) {}
    }

    if (spawnResult.error) {
      return { accept: false, reason: 'harness process error: ' + String(spawnResult.error.message || spawnResult.error) };
    }
    if (spawnResult.signal) {
      return { accept: false, reason: 'harness process was killed (signal ' + spawnResult.signal + ') \u2014 suite did not complete, likely a hang or forced termination' };
    }

    let finalData = null;
    try {
      const raw = fs.readFileSync(finalFile, 'utf8');
      finalData = JSON.parse(raw);
    } catch (e) {
      return { accept: false, reason: 'harness did not produce a completion record \u2014 suite did not run to completion (possible early exit or crash)' };
    } finally {
      try { fs.unlinkSync(finalFile); } catch (e) {}
      try { fs.unlinkSync(progressFile); } catch (e) {}
    }

    if (!finalData || finalData.completed !== true) {
      return { accept: false, reason: 'harness completion record malformed or missing completed flag' };
    }
    if (finalData.importError) {
      return { accept: false, reason: 'failed to import dedupeSorted from answer.mjs: ' + finalData.importError };
    }
    if (finalData.evalError) {
      return { accept: false, reason: 'error while executing pinned test cases: ' + finalData.evalError };
    }
    if (finalData.total !== expectedCount) {
      return { accept: false, reason: 'expected ' + expectedCount + ' pinned test cases to run, but only ' + finalData.total + ' completed \u2014 suite did not run to completion' };
    }
    if (Array.isArray(finalData.uncaught) && finalData.uncaught.length > 0) {
      return { accept: false, reason: 'uncaught exception(s) occurred outside test bodies: ' + finalData.uncaught.join(' | ') };
    }
    if (Array.isArray(finalData.unhandled) && finalData.unhandled.length > 0) {
      return { accept: false, reason: 'unhandled promise rejection(s) occurred: ' + finalData.unhandled.join(' | ') };
    }
    const failed = (finalData.results || []).filter(function (r) { return !r.pass; });
    if (failed.length > 0) {
      return {
        accept: false,
        reason: failed.length + '/' + expectedCount + ' pinned test case(s) failed: ' +
          failed.map(function (r) { return '"' + r.name + '": ' + r.error; }).join(' ; '),
      };
    }

    return { accept: true, reason: 'all ' + expectedCount + " pinned test cases passed against the submission's own dedupeSorted, verified via an isolated child process with its own completion record" };
  } catch (e) {
    return { accept: false, reason: 'gate internal error: ' + String(e && e.stack ? e.stack : e) };
  }
}

